function TopicField({ label }) {
  const id = React.useId();
  const hintId = id + "-hint";
  return (
    <section>
      <label htmlFor={id}>{label}</label>
      <input id={id} aria-describedby={hintId} />
      <p id={hintId}>Use a short topic name.</p>
    </section>
  );
}
function App() {
  const [version, setVersion] = React.useState(0);
  return (
    <main>
      <button onClick={() => setVersion(v => v + 1)}>Rerender {version}</button>
      <TopicField label="First topic" />
      <TopicField label="Second topic" />
    </main>
  );
}
```
Each label and hint points to its own input. The fields have different IDs even though they use the same component.
